schema:
{
  "description": "Offerte commerciali in Word",
  "baseAnalyzerId": "prebuilt-document",
  "config": {
    "estimateFieldSourceAndConfidence": true
  },
  "fieldSchema": {
    "fields": {
      "Cliente": {
        "type": "string",
        "method": "extract",
        "description": "Destinatario dopo \"Spett.le\"."
      },
      "DataOfferta": {
        "type": "date",
        "method": "extract",
        "description": "Data in intestazione, accanto alla città."
      },
      "Importo": {
        "type": "number",
        "method": "extract",
        "description": "Importo complessivo dell'offerta, IVA esclusa."
      },
      "ScontoPercento": {
        "type": "number",
        "method": "extract",
        "description": "Percentuale di sconto riconosciuta; 0 se l'importo è già netto."
      },
      "GiorniValidita": {
        "type": "number",
        "method": "extract",
        "description": "Giorni di validità dell'offerta."
      }
    }
  }
}
